# 모습별 말투 필터: 이 모습일 때 자동으로 나오는 말풍선을 바꿔 줌 (Claude 대답 말풍선은 그대로)
DORO_LINES = ["도로롱~", "도로롱도로롱", "도로…?", "도로로로롱!", "도로 도로 도로롱♪", "도로롱?",
              "도로도로도로!!", "도로롱…", "도로!", "롱~", "도로로롱~♪", "도로? 도로롱!"]
DORO_RE = re.compile(r"[도로롱오옹\s~!?…♪.,\-]+")

def doro_only(text):
    """도로롱 모습: '도로/도로롱/롱' 소리만 남기기 (사람 말이 섞이면 도로롱 소리로 바꿈)"""
    t = str(text).strip()
    if t and "도로" in t and DORO_RE.fullmatch(t):
        return t
    n = max(1, min(4, len(t) // 25 + 1))      # 대답이 길수록 조금 더 길게 도로도로
    return " ".join(random.choice(DORO_LINES) for _ in range(n))
MODERNIA_LINES = ["지히간!", "지히간 어디 가요?", "붕대 좋아해요!", "저 잘했나요?", "이거 뭐예요? 먹는 거예요?",
                  "라피가 가르쳐줬는데…", "가만히 있기 놀이 해요!", "디스카운트!", "같이 놀아요!", "지히간 냄새 나요!"]
