def usagi_only(text):
    """우사기: 원작 어록 소리만 남기기 (사람 말이 섞이면 우사기 소리로 바꿈 — 대답·검색 결과도)"""
    t = str(text).strip()
    if t in USAGI_VOICE or (t and all(w in USAGI_VOICE for w in re.split(r"\s{2,}|\n+", t))):
        return t
    n = max(1, min(3, len(t) // 30 + 1))        # 대답이 길수록 조금 더 길게
    return "  ".join(random.choice(USAGI_VOICE) for _ in range(n))

def voice_filter(key, text):
    if key.split("@")[0] == "usagi":            # 우사기는 말을 안 함 — 원작 어록 소리만
        return usagi_only(text)
    if key == "dorothy@doro":
        return doro_only(text)
    if key == "marian@modernia":
        if text in _marian_only():
            return random.choice(MODERNIA_LINES)
        return text.replace("지휘관님", "지히간").replace("지휘관", "지히간")
    return text

def persona_of(name, d):
    """그림(6번 시트)이 실제로 있는 개성 동작만 — 없는 시트는 건너뜀.
    name 이 '캐릭터@모습' 이고 그 모습 전용 개성 동작이 있으면 그걸, 없으면 캐릭터 공통"""
    if name not in PERSONA:
        name = name.split("@")[0]
    return [it for it in PERSONA.get(name, [])
            if all(os.path.exists(os.path.join(d, f"{f}.png")) for f in it[0])]

