CHAR_BIO.update({
    "laplus": ("홀로라이브 6기생 홀로엑스의 총수 라플라스 다크니스(라프). 은백색 긴 머리에 보라 브릿지, 보라 줄무늬의 큰 검은 뿔, 손을 덮는 긴 소매의 보라색 코트와 족쇄, 별 사슬 꼬리. "
               "자신을 '이 몸(吾輩)', 상대를 '네놈'이라 부르는 거만한 말투지만 139cm로 홀로라이브에서 가장 작아 선배들에게 아기 취급받는 밈. 팬은 '플러스메이트', 구호는 '예스 마이 다크'. "
               "오랜 동료 까마귀가 곁에 있음. 'YMD'가 '야마다'로 읽혀 야마다라고 불리는 밈. 게임에 지면 크게 화냄. 토와의 노래를 아주 좋아함."),
    "lui": ("홀로라이브 6기생 홀로엑스의 간부 타카네 루이. 짧은 분홍 머리의 매, 자주색 망토와 흰 블라우스. 인사는 '기다렸지?', 팬은 '루이토모'. "
            "홀로엑스의 실질적 리더이자 라프와 클로에를 챙기는 언니. 아재개그를 좋아하고, 중요한 순간에 실수하는 밈(소리 안 지르기 도전 전에 물컵을 엎음). "
            "뾰족한 물건과 호러를 무서워함. 매운 음식·피클·레드와인을 좋아함. 비서는 통통한 개구리입쏙독새 '간모'(머리 위 아기 새 두 마리)."),
    "koyori": ("홀로라이브 6기생 홀로엑스의 연구개발 책임자 하쿠이 코요리. 분홍 긴 머리의 코요테(여우·고양이 아님), 흰 실험 가운과 시험관 벨트. 인사는 '콘코요~', 팬은 '조수 군'. "
               "자칭 '홀로엑스의 두뇌'지만 실력은 애매한 밈. 인간 관찰이 취미이고 일부러 장난쳐서 반응을 봄. 파트너 로봇 '코코로', 팬아트에서 나온 복슬복슬 '모후코요'. "
               "라멘·고기·마요네즈를 좋아하고 호러·벌레·아침을 싫어함. 인형 뽑기를 좋아함."),
    "chloe": ("홀로라이브 6기생 홀로엑스의 청소부(인턴) 사카마타 클로에. 범고래 후드, 은회색 머리, 빨간 눈, 검은 재킷과 빨간 체크 치마. 인사는 '바쿠바쿠~', 팬은 '사육사'. "
              "청소부인데 방이 쓰레기로 가득하다는 밈, 목욕은 사흘에 한 번, 반나절씩 자는 잠꾸러기. 음악을 아주 좋아함. 마스코트는 구명조끼를 입은 아기 범고래 '이누'. "
              "호러·벌레를 싫어함. 2025년 1월에 활동을 마치고 홀로라이브 어필리에이트가 됨."),
    "iroha": ("홀로라이브 6기생 홀로엑스의 경호원 카자마 이로하. 금발 포니테일의 사무라이(닌자), 크림색 하오리, 등에 멘 일본도 '차키마루'. 말끝에 '고자루(~소이다)'를 붙임, 팬은 '카자마대'. "
              "홀로엑스의 '보험'. 근육뇌 소리를 듣지만 순수하고 상냥함, 은근 덜렁이. 동료 너구리 '포코베'. 고양이·우동·링피트를 좋아하고 호러·벌레·장어를 싫어함."),
})
