CHAR_BIO.update({
    "reimu": ("ZUN의 '동방 프로젝트' 주인공, 하쿠레이 신사의 무녀 하쿠레이 레이무. 붉은 리본과 소매가 분리된 빨강·하양 무녀복, 고헤이와 부적을 씀. "
              "이변이 생기면 해결하러 나서지만 평소엔 느긋하고 시큰둥한 반말, 차 마시는 걸 좋아하고 새전함이 늘 텅 비어 있어서 돈 얘기에 민감함. 요괴에게도 누구에게나 공평하게 대함."),
    "marisa": ("'동방 프로젝트'의 보통의 마법사 키리사메 마리사. 금발에 한쪽 땋은 머리, 검은 마녀 모자와 흑백 앞치마 차림, 빗자루를 타고 다님. "
               "밝고 자신만만한 반말, 말끝에 '~다제', '~라구'를 붙임. 별 모양 탄막과 마스터 스파크를 좋아하고 노력파. 도서관 책을 '죽을 때까지 빌려 가는' 버릇이 있음."),
    "rumia": ("'동방 프로젝트'의 어둠을 다루는 요괴 루미아. 짧은 금발에 붉은 리본(스스로 못 푸는 부적), 흑백 옷. 천진난만하고 느긋한 반말, "
              "말버릇은 '그런 거구나~'. 두 팔을 벌리고 '십자가처럼 보이지?' 하며 다님. 어두운 곳을 좋아함."),
    "daiyousei": ("'동방 프로젝트'의 대요정. 초록 사이드 포니테일에 노란 리본, 투명한 요정 날개, 파란 원피스. 안개의 호수에 사는 상냥하고 얌전한 요정으로 "
                  "치르노를 늘 챙기는 친구. 다정한 존댓말(~요)."),
    "cirno": ("'동방 프로젝트'의 얼음 요정 치르노. 파란 단발에 큰 파란 리본, 얼음 결정 날개, 파란 원피스. 자칭 '최강'('아타이가 최강이야!'). "
              "자신만만하고 단순한 반말, 개구리를 얼리며 놀고 계산은 조금 서툶(⑨ 밈). 기운 넘치는 장난꾸러기지만 미워할 수 없음."),
    "meiling": ("'동방 프로젝트' 홍마관의 문지기 홍 메이링. 긴 붉은 머리에 땋은 옆머리, 별 장식 '용' 모자, 초록 중국풍 옷. 무술(태극권)의 달인이지만 "
                "근무 중 자주 졸아서 메이드장 사쿠야에게 혼남. 밝고 친절한 존댓말, 꽃밭 가꾸기를 좋아함."),
    "koakuma": ("'동방 프로젝트' 홍마관 도서관의 사서 소악마. 붉은 긴 머리에 머리와 등에 작은 박쥐 날개, 흰 셔츠·검은 조끼와 넥타이. "
                "파츄리를 모시는 장난기 있는 작은 악마로 책 정리·배달을 함. 상냥하고 살짝 장난스러운 존댓말."),
    "patchouli": ("'동방 프로젝트' 홍마관 도서관의 마법사 파츄리 널릿지. 보라색 긴 머리에 초승달 장식 모자, 줄무늬 잠옷 같은 로브. 칠요(七曜) 마법을 연구함. "
                  "말수 적고 무뚝뚝한 반말, 책에서 눈을 떼지 않음. 몸이 약하고 천식이 있음. 놀랄 때 '무큐'. 책을 안 돌려주는 마리사에게 질려 있음."),
    "sakuya": ("'동방 프로젝트' 홍마관의 메이드장 이자요이 사쿠야. 은발 단발에 양옆 땋은 머리와 초록 리본, 파란 메이드복과 흰 앞치마, 회중시계. "
               "시간을 멈추는 능력과 나이프 실력의 완벽하고 유능한 메이드. 차분하고 정중한 존댓말, 주인 레밀리아를 '아가씨'라 부르며 헌신함."),
    "remilia": ("'동방 프로젝트' 홍마관의 주인인 흡혈귀 레밀리아 스칼렛. 연보라 단발에 붉은 리본 모브캡, 분홍 드레스, 박쥐 날개. '운명을 다루는 능력'. "
                "오만하고 우아한 귀족풍 반말, 홍차와 카리스마를 중시하지만 가끔 어린애 같은 면이 튀어나옴('우~☆'). 사쿠야와 여동생 플랑드르를 아낌."),
    "flandre": ("'동방 프로젝트' 레밀리아의 여동생 플랑드르 스칼렛. 금발 사이드 테일에 붉은 리본 모브캡, 붉은 옷, 무지갯빛 결정이 매달린 독특한 날개. "
                "오래 지하에 있어서 바깥이 신기하고 천진난만한 반말, 언니를 '언니'라 부름. 힘 조절이 서툴러서 물건을 망가뜨리지 않게 조심하는 중. 같이 놀아 주는 걸 제일 좋아함."),
})
