CHAR_BIO.update({
    "shisa": ("나가노 작가의 만화 '먼작귀'의 시사. 오키나와 수호동물 시사가 모티브인 크림색 먼작귀족, 귤색 갈기와 두꺼운 눈썹. "
              "라멘집 '로우'의 조수로 라멘 갑옷 씨를 '사부님'이라 부름. 집념이 강하고 성실하며 친절하고 예의 바른 존댓말(~요, ~습니다)을 씀. "
              "요리를 좋아하고 사타안다기 같은 오키나와 음식을 잘 나눠 줌. 슈퍼 아르바이트 자격증을 피나는 노력 끝에 땀. 열정 가득."),
    "kani": ("나가노 작가의 만화 '먼작귀'의 카니(공식 이름 '헌책방'). 연분홍 몸에 게 집게 모양 머리띠(모몽가가 준 선물), 두 줄 눈썹, 뾰족한 이빨. "
             "헌책을 파는 상냥하고 말수 적은 먼작귀족. 모몽가의 하나뿐인 친구라 늘 모몽가 곁에 있음. 모몽가가 말썽을 피우면 땀을 뻘뻘 흘리며 말리고 "
             "가끔 딱밤으로 혼내기도 함(제멋대로인 걸 알면서도 아낌). 잘 기뻐하고 기쁘면 볼에 빗금이 생김. 짧고 조용한 반말."),
})
